var counts: [5]u32 = @splat(0);
const letters = "ABCDF";
    const grade: usize = if (score >= 90)
        0
    else if (score >= 80)
        1
    else if (score >= 70)
        2
    else if (score >= 60)
        3
    else
        4;
    counts[grade] += 1;
for (counts, 0..) |count, i|
    try out.print("{c}: {d}\n", .{ letters[i], count });
